-- ============================================
-- LUMA — Thème 1 (Restaurant) : scénario MOYEN 2/3 x4 — Se plaindre poliment d'un plat
-- ============================================


update scenarios set content = '{"characters": {"waiter": "le serveur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "waiter", "text": "Here''s your steak, sir. Enjoy!", "text_fr": "Voici votre steak, monsieur. Bon appétit !", "choices": [{"text": "Wait — I asked for medium, and this looks well done.", "text_fr": "Attendez — j''avais demandé à point, et ça semble très cuit.", "next": "n2"}, {"text": "Thank you. (You cut into it and notice it''s overcooked.)", "text_fr": "Merci. (Vous le coupez et remarquez qu''il est trop cuit.)", "next": "n2b"}]}, "n2": {"speaker": "waiter", "text": "Oh, I''m sorry about that. Let me check with the kitchen right away.", "text_fr": "Oh, je suis désolé pour ça. Je vérifie avec la cuisine tout de suite.", "choices": [{"text": "Thank you, I''d really appreciate that.", "text_fr": "Merci, j''apprécierais vraiment.", "next": "n3"}]}, "n2b": {"speaker": "waiter", "text": "(A moment later) Is everything alright with your meal?", "text_fr": "(Un instant plus tard) Tout va bien avec votre repas ?", "choices": [{"text": "Actually, no — this steak is more well done than I asked for.", "text_fr": "En fait, non — ce steak est plus cuit que ce que j''avais demandé.", "next": "n3"}, {"text": "It''s fine, I''ll just eat it.", "text_fr": "C''est bon, je vais juste le manger.", "next": "n3c"}]}, "n3": {"speaker": "waiter", "text": "I completely understand, that''s on us. Would you like a new one cooked medium?", "text_fr": "Je comprends totalement, c''est de notre faute. Vous voulez un nouveau steak cuit à point ?", "choices": [{"text": "Yes, that would be great, thank you.", "text_fr": "Oui, ce serait super, merci.", "next": "n4"}, {"text": "Actually, could I switch to a different dish instead?", "text_fr": "En fait, je pourrais changer pour un autre plat plutôt ?", "next": "n4b"}]}, "n3c": {"speaker": "waiter", "text": "Are you sure? I''d be happy to have the kitchen redo it properly.", "text_fr": "Vous êtes sûr ? Je serais content de faire refaire ça correctement en cuisine.", "choices": [{"text": "Actually, you''re right, let''s get it fixed.", "text_fr": "En fait, vous avez raison, faisons-le corriger.", "next": "n3"}, {"text": "No really, it''s fine, thank you for asking.", "text_fr": "Non vraiment, c''est bon, merci de demander.", "next": "end_settled"}]}, "n4": {"speaker": "waiter", "text": "Of course, I''ll have that out to you shortly, and I''ll speak to the chef.", "text_fr": "Bien sûr, je vous l''apporte bientôt, et je vais en parler au chef.", "choices": [{"text": "Thank you, I appreciate you handling this.", "text_fr": "Merci, j''apprécie que vous gériez ça.", "next": "n5"}]}, "n4b": {"speaker": "waiter", "text": "Absolutely, no problem. What would you like instead?", "text_fr": "Absolument, aucun problème. Qu''est-ce que vous voudriez à la place ?", "choices": [{"text": "The salmon looked good on the menu.", "text_fr": "Le saumon avait l''air bon sur le menu.", "next": "n5b"}, {"text": "Maybe something simpler, like the pasta.", "text_fr": "Peut-être quelque chose de plus simple, comme les pâtes.", "next": "n5b"}]}, "n5": {"speaker": "waiter", "text": "Here''s your new steak, cooked medium as requested. My apologies again.", "text_fr": "Voici votre nouveau steak, cuit à point comme demandé. Encore désolé.", "choices": [{"text": "This looks perfect, thank you.", "text_fr": "Ça a l''air parfait, merci.", "next": "n6"}, {"text": "No worries, these things happen.", "text_fr": "Pas de souci, ça arrive.", "next": "n6"}]}, "n5b": {"speaker": "waiter", "text": "Great choice, I''ll get that started right away, no charge for the mix-up.", "text_fr": "Excellent choix, je lance ça tout de suite, pas de frais pour l''erreur.", "choices": [{"text": "That''s very kind, thank you.", "text_fr": "C''est très gentil, merci.", "next": "n6"}]}, "n6": {"speaker": "waiter", "text": "Would you like anything else while you wait, on the house?", "text_fr": "Vous voulez autre chose en attendant, offert par la maison ?", "choices": [{"text": "A glass of wine would be nice, thank you.", "text_fr": "Un verre de vin serait sympa, merci.", "next": "n7"}, {"text": "That''s really not necessary, but thank you.", "text_fr": "Ce n''est vraiment pas nécessaire, mais merci.", "next": "n7b"}]}, "n7": {"speaker": "waiter", "text": "Of course, I''ll bring that right over.", "text_fr": "Bien sûr, je vous l''apporte tout de suite.", "choices": [{"text": "Thank you, this makes up for it nicely.", "text_fr": "Merci, ça compense bien.", "next": "end_satisfied"}]}, "n7b": {"speaker": "waiter", "text": "You''re very gracious about this. I really appreciate that.", "text_fr": "Vous êtes très compréhensif sur ce coup. J''apprécie vraiment ça.", "choices": [{"text": "These things happen, no hard feelings.", "text_fr": "Ça arrive, pas de rancune.", "next": "end_gracious"}]}, "end_satisfied": {"speaker": "waiter", "text": "Enjoy the rest of your meal, and thank you for your patience!", "text_fr": "Profitez du reste de votre repas, et merci pour votre patience !", "end": true, "ending_label": "Plainte résolue avec satisfaction 🍽️✅"}, "end_gracious": {"speaker": "waiter", "text": "Thank you for being so understanding. Enjoy your meal!", "text_fr": "Merci d''être aussi compréhensif. Bon appétit !", "end": true, "ending_label": "Situation gérée avec élégance et calme 😊"}, "end_settled": {"speaker": "waiter", "text": "Alright, please let me know if you change your mind. Enjoy!", "text_fr": "D''accord, dites-moi si vous changez d''avis. Bon appétit !", "end": true, "ending_label": "Repas accepté tel quel, sans faire de vagues 🤷"}}}'::jsonb, is_playable = true
where title = 'Se plaindre poliment d''''un plat'
  and theme_id = (select id from scenario_themes where position = 1 and language_id = (select id from languages where code = 'en'));
